style.css:
@-moz-document domain("youtube.com") {
/* 1. HIDE THE RED DOT */
    .ytp-scrubber-button {
        background: transparent !important;
        border: none !important;
        box-shadow: none !important;
    }

    /* 2. PIKACHU ANIMATION */
    .ytp-scrubber-button:after {
        content: "";
        display: block;
        width: 55px;   /* Slightly bigger for better visibility */
        height: 55px;
        
        background: url("https://media.tenor.com/uUNcnHwYJQEAAAAj/running-pikachu-transparent-snivee.gif") no-repeat center;
        background-size: contain;
        
        position: absolute;
        top: -28px;    /* Feet on the line */
        left: -15px;
        
        /* NO FLIP APPLIED - He runs Right naturally */
        transform: none !important; 
    }

    /* 3. ELECTRIC YELLOW BAR & GLOW */
    .ytp-play-progress {
        background: #ffe600 !important; 
        box-shadow: 0 0 15px #ffe600, 0 0 5px #ffcc00 !important; /* Electric Glow */
    }

    /* 4. HOVER EFFECT (He gets excited/bigger when you grab him) */
    .ytp-scrubber-button:hover:after {
        transform: scale(1.1) !important; 
        filter: drop-shadow(0 0 5px #ffe600);
    }
}
